PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS applications (id TEXT PRIMARY KEY, applicant_name TEXT NOT NULL, dob TEXT, phone TEXT, email TEXT, loan_type TEXT NOT NULL, requested_amount REAL, declared_income REAL, employer TEXT, employment_type TEXT, purpose TEXT, status TEXT NOT NULL DEFAULT 'Submitted', created_at TEXT NOT NULL, owner_user_id TEXT NOT NULL DEFAULT 'demo');
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'applicant' CHECK (role IN ('applicant','officer')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS application_access (application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE, officer_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(application_id,officer_user_id));
CREATE TABLE IF NOT EXISTS application_invites (code_hash TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE, applicant_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, accepted_by TEXT REFERENCES users(id) ON DELETE SET NULL, accepted_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_application_access_officer ON application_access(officer_user_id);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE, file_name TEXT NOT NULL, document_type TEXT NOT NULL, storage_path TEXT NOT NULL, file_hash TEXT NOT NULL, size_bytes INTEGER NOT NULL, quality_status TEXT NOT NULL, processing_status TEXT NOT NULL, extracted_json TEXT NOT NULL DEFAULT '{}', uploaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checks (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE, check_type TEXT NOT NULL, result TEXT NOT NULL, explanation TEXT NOT NULL, evidence_json TEXT NOT NULL, confidence REAL NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE, agent TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE, requested_document TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_cases (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE, reason TEXT NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', resolution_notes TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_documents_app ON documents(application_id);
CREATE INDEX IF NOT EXISTS idx_checks_app ON checks(application_id);
CREATE INDEX IF NOT EXISTS idx_events_app ON events(application_id);
